(7552637, 1210069, 138721, '<td valign="top">Really nice, I love the texture on her face and the composition. One of my favourites!</td>', 'Really nice, I love the texture on her face and the composition. One of my favourites!', '2018-01-14 18:09:48.000000', NULL, 1),
(7552675, 1209904, 94815, '<td valign="top">Cute and colorful.</td>', 'Cute and colorful.', '2018-01-14 23:33:09.000000', NULL, 1),
(7552681, 1209990, 94815, '<td valign="top">Hardly could be better in terms of subject, exposure and color rendition. I''m slightly troubled by her unstable placement too far to the left by just a tad. Following the Renaissance convention usually solves the instability by locking an eye dead center of the composition. 8</td>', 'Hardly could be better in terms of subject, exposure and color rendition. I''m slightly troubled by her unstable placement too far to the left by just a tad. Following the Renaissance convention usually solves the instability by locking an eye dead center of the composition. 8', '2018-01-14 23:47:39.000000', NULL, 1),
(7552683, 1210243, 94815, '<td valign="top">Sparklingly adorable.</td>', 'Sparklingly adorable.', '2018-01-14 23:48:11.000000', NULL, 1),
(7552688, 1210239, 94815, '<td valign="top">Brilliant idea to use the fisheye to focus attention "in your face" so to speak. Result is an unabashedly intimate portrait.</td>', 'Brilliant idea to use the fisheye to focus attention "in your face" so to speak. Result is an unabashedly intimate portrait.', '2018-01-14 23:53:09.000000', NULL, 1),
